package com.shopsphere.dao;
import com.shopsphere.model.*;
import com.shopsphere.util.DBConnection;
import java.sql.*;
import java.util.*;
public class CartDAO {
    public Cart getOrCreateCartForUser(Long userId) { try (Connection c = DBConnection.getConnection()) { try (PreparedStatement p = c.prepareStatement("SELECT id,user_id FROM carts WHERE user_id=?")) { p.setLong(1, userId); try (ResultSet r = p.executeQuery()) { if (r.next()) { Cart ca = new Cart(); ca.setId(r.getLong("id")); ca.setUserId(r.getLong("user_id")); ca.setItems(getCartItems(ca.getId())); return ca; } } } try (PreparedStatement p = c.prepareStatement("INSERT INTO carts (user_id) VALUES (?)", Statement.RETURN_GENERATED_KEYS)) { p.setLong(1, userId); p.executeUpdate(); try (ResultSet k = p.getGeneratedKeys()) { if (k.next()) { Cart ca = new Cart(); ca.setId(k.getLong(1)); ca.setUserId(userId); ca.setItems(new ArrayList<>()); return ca; } } } } catch (SQLException e) {} return null; }
    public List<CartItem> getCartItems(Long cartId) { List<CartItem> l = new ArrayList<>(); try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("SELECT ci.id AS item_id, ci.cart_id, ci.product_id, ci.quantity, p.id AS prod_id, p.category_id, p.name AS prod_name, p.brand, p.description, p.price, p.discount, p.stock, p.image_url, p.status FROM cart_items ci JOIN products p ON ci.product_id=p.id WHERE ci.cart_id=? AND p.status='ACTIVE'")) { p.setLong(1, cartId); try (ResultSet r = p.executeQuery()) { while (r.next()) { CartItem ci = new CartItem(); ci.setId(r.getLong("item_id")); ci.setCartId(r.getLong("cart_id")); ci.setProductId(r.getLong("product_id")); ci.setQuantity(r.getInt("quantity")); Product pr = new Product(); pr.setId(r.getLong("prod_id")); pr.setCategoryId(r.getInt("category_id")); pr.setName(r.getString("prod_name")); pr.setBrand(r.getString("brand")); pr.setDescription(r.getString("description")); pr.setPrice(r.getBigDecimal("price")); pr.setDiscount(r.getBigDecimal("discount")); pr.setStock(r.getInt("stock")); pr.setImageUrl(r.getString("image_url")); pr.setStatus(Product.Status.valueOf(r.getString("status"))); ci.setProduct(pr); l.add(ci); } } } catch (SQLException e) {} return l; }
    public void addItem(Long cartId, Long prodId, int qty) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("INSERT INTO cart_items (cart_id,product_id,quantity) VALUES (?,?,?) ON DUPLICATE KEY UPDATE quantity=quantity+VALUES(quantity)")) { p.setLong(1, cartId); p.setLong(2, prodId); p.setInt(3, qty); p.executeUpdate(); } catch (SQLException e) {} }
    public void updateItemQuantity(Long cartId, Long prodId, int qty) { if (qty <= 0) { removeItem(cartId, prodId); return; } try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("UPDATE cart_items SET quantity=? WHERE cart_id=? AND product_id=?")) { p.setInt(1, qty); p.setLong(2, cartId); p.setLong(3, prodId); p.executeUpdate(); } catch (SQLException e) {} }
    public void removeItem(Long cartId, Long prodId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("DELETE FROM cart_items WHERE cart_id=? AND product_id=?")) { p.setLong(1, cartId); p.setLong(2, prodId); p.executeUpdate(); } catch (SQLException e) {} }
    public void clearCart(Long cartId) { try (Connection c = DBConnection.getConnection(); PreparedStatement p = c.prepareStatement("DELETE FROM cart_items WHERE cart_id=?")) { p.setLong(1, cartId); p.executeUpdate(); } catch (SQLException e) {} }
}
